#!/usr/bin/env python3
"""Refresh the files Renovate cannot update itself in an update branch (#2999).

Renovate bumps a version in a manifest, but two files derived from manifests stay
stale. Each task below is a post-upgrade command (``.github/renovate.json``) run in the
branch checkout, the current directory, and acts only on the upgrades it owns::

    python3 renovate_artifacts.py agent-cli-lock   # agent-clis-package.json -> its lock
    python3 renovate_artifacts.py constraints      # pyproject.toml -> CI constraints

``agent-cli-lock``: Renovate's npm manager recognises the manifest by name but cannot
find ``agent-clis-package-lock.json``, so the lock would no longer match the bumped
manifest. The manifest and lock are copied under npm's names into a temporary
directory, where ``npm install --package-lock-only`` updates the lock; the result
replaces the repository lock.

``constraints``: ``.github/ci/constraints.txt`` pins every dependency for CI
(``ci_constraints.py`` checks it). The command in its header regenerates it. Renovate
checks a pin PR's constraints with the same file, so a bumped ``pyproject.toml`` pin
leaves it stale. uv keeps the existing pins as preferences, so only the bumped pin and
what it pulls in change.

The branch is data. npm runs where only the two copies exist (so a branch ``.npmrc``
is never read) and ``--ignore-scripts`` blocks package scripts. uv runs with
``--no-build`` (no build backend of the project executes) and ``--no-config`` (no
``[tool.uv]`` table or ``uv.toml`` of the branch is read). The script itself comes from
the runner's default-branch checkout. Stdlib-only: it runs in the Renovate container.

Exit 0: done, or nothing to do. Exit 1: a tool failed, timed out or is missing, or the
constraints header is not the command the check requires; the repository file is left
as it was and the message reaches the PR as an artifact error. Exit 2: unusable data
file or arguments.
"""

from __future__ import annotations

import argparse
import re
import shlex
import shutil
import subprocess
import sys
import tempfile
from collections.abc import Sequence
from pathlib import Path

from renovate_data_file import Upgrade, data_file_path, load_upgrades

AGENT_CLI_MANIFEST = "src/booley/data/docker/agent-clis-package.json"
AGENT_CLI_LOCK = "src/booley/data/docker/agent-clis-package-lock.json"
CONSTRAINTS_FILE = ".github/ci/constraints.txt"
PYPROJECT = "pyproject.toml"

# What ``ci_constraints.regenerate_command`` produces: nothing else is run from a header.
_COMPILE_COMMAND = re.compile(
    r"uv pip compile pyproject\.toml --all-extras --universal"
    r" --python-version \d+\.\d+ -o \.github/ci/constraints\.txt"
)
_HEADER_LINE = 1  # zero-based: the line after "autogenerated by uv via the following command"
_NPM_ARGUMENTS = ["install", "--package-lock-only", "--ignore-scripts", "--no-audit", "--no-fund"]
_TIMEOUT_SECONDS = 600


class ArtifactError(Exception):
    """A task cannot refresh its file; the file is left as it was (exit 1)."""


def _run_tool(argv: list[str], cwd: Path) -> None:
    """Run ``argv`` without a shell; raise ``ArtifactError`` with its stderr on failure."""
    name = argv[0]
    try:
        result = subprocess.run(
            argv,
            cwd=cwd,
            capture_output=True,
            text=True,
            timeout=_TIMEOUT_SECONDS,
            check=False,
        )
    except subprocess.TimeoutExpired as error:
        raise ArtifactError(f"{name} timed out after {_TIMEOUT_SECONDS}s") from error
    except OSError as error:
        raise ArtifactError(f"cannot run {name}: {error}") from error
    if result.returncode != 0:
        raise ArtifactError(f"{name} exited {result.returncode}:\n{result.stderr.strip()}")


def _upgrades_file(upgrades: Sequence[Upgrade], package_file: str) -> bool:
    return any(upgrade.package_file == package_file for upgrade in upgrades)


def agent_cli_lock(root: Path) -> None:
    """Regenerate the agent CLI lock from the manifest by npm, in a scratch directory."""
    lock = root / AGENT_CLI_LOCK
    with tempfile.TemporaryDirectory(prefix="agent-cli-lock-") as scratch_name:
        scratch = Path(scratch_name)
        try:
            shutil.copyfile(root / AGENT_CLI_MANIFEST, scratch / "package.json")
            shutil.copyfile(lock, scratch / "package-lock.json")
        except OSError as error:
            raise ArtifactError(f"cannot copy the agent CLI manifest and lock: {error}") from error
        _run_tool(["npm", *_NPM_ARGUMENTS], scratch)
        # Replace atomically: a crash must not leave half a lock in the repository.
        staged = lock.with_name(f".{lock.name}.renovate.tmp")
        try:
            shutil.copyfile(scratch / "package-lock.json", staged)
            staged.replace(lock)
        except OSError as error:
            staged.unlink(missing_ok=True)
            raise ArtifactError(f"cannot write {AGENT_CLI_LOCK}: {error}") from error


def constraints(root: Path) -> None:
    """Regenerate the CI constraints file with the command in its own header."""
    try:
        lines = (root / CONSTRAINTS_FILE).read_text(encoding="utf-8").splitlines()
    except (OSError, UnicodeDecodeError) as error:
        raise ArtifactError(f"cannot read {CONSTRAINTS_FILE}: {error}") from error
    header = lines[_HEADER_LINE].removeprefix("#").strip() if len(lines) > _HEADER_LINE else ""
    if _COMPILE_COMMAND.fullmatch(header) is None:
        raise ArtifactError(
            f"{CONSTRAINTS_FILE} line {_HEADER_LINE + 1} is not the expected compile command"
        )
    # uv resolves before it writes, so a failed resolution leaves the file untouched.
    _run_tool(
        [
            *shlex.split(header),
            "--no-build",
            "--no-config",
            "--custom-compile-command",
            header,
        ],
        root,
    )


def main(argv: Sequence[str] | None = None) -> int:
    """Run one task in the current directory; return the exit code."""
    parser = argparse.ArgumentParser(description="Refresh files derived from bumped manifests.")
    parser.add_argument("task", choices=["agent-cli-lock", "constraints"])
    args = parser.parse_args(argv)
    try:
        upgrades = load_upgrades(data_file_path(None))
    except ValueError as error:
        print(f"error: {error}", file=sys.stderr)
        return 2
    trigger = AGENT_CLI_MANIFEST if args.task == "agent-cli-lock" else PYPROJECT
    if not _upgrades_file(upgrades, trigger):
        print(f"{args.task}: no upgrade of {trigger}, nothing to do", file=sys.stderr)
        return 0
    try:
        (agent_cli_lock if args.task == "agent-cli-lock" else constraints)(Path.cwd())
    except ArtifactError as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    print(f"{args.task}: refreshed")
    return 0


if __name__ == "__main__":
    sys.exit(main())
